)) !== 36); } }, { id: "c_otherwise_501", fn: function(){ return (!(((dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 32 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 33 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 34 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 36))); } }, { id: "if_rsltNotiDd", fn: function(){ return ((dma_specyvaluInfo.get("rsltNotiDd") ?? (() => { throw new Error("unresolved:" + "specyvaluInfo.rsltNotiDd"); })()) !== ''); } }, { id: "if_ldMktTpCd", fn: function(){ return ((dma_comInfo.get("ldMktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.ldMktTpCd"); })()) === '2' || (dma_comInfo.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.spotIsuTrdMktTpCd"); })()) === '2' || (dma_comInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "comInfo.mktTpCd"); })()) === '2'); } }, { id: "if_secugrpId_3", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) ==='FS'); } }, { id: "if_secugrpId_4", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'DR'); } }, { id: "if_secugrpId_5", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'RT'); } }, { id: "btn_Register", fn: function(){ return ((dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 32 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 33 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 34 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 36); } }];
