/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_page", fn: function () { return String(String((dma_pageContext.get("page") ?? ""))); } },
        { childId: "ipt_type", fn: function () { return String(String((dma_pageContext.get("type") ?? ""))); } },
        { childId: "ipt_ldMktTpCd", fn: function () { return String(((String(dma_comInfo.get("spotIsuTrdMktTpCd")) === String((dma_pageContext.get("ldMktTpCd") ?? ""))) ? String((dma_pageContext.get("ldMktTpCd") ?? "")) : String(dma_comInfo.get("spotIsuTrdMktTpCd")))); } },
        { childId: "ipt_listTpClssCd", fn: function () { return String((dma_pageContext.get("listTpClssCd") ?? "")); } },
        { childId: "ipt_comAbbrv", fn: function () { return String(String(dma_comInfo.get("comNm")).substring(0, 20)); } },
        { childId: "__rb0", fn: function () { return String(((String(dma_comInfo.get("listTpClssCd")) === "02") ? "상장법인" : "심사진행법인")); } },
        { childId: "__rb1", fn: function () { return String(((String(dma_comInfo.get("listTpClssCd")) === "02") ? String(dma_defaultMap.get("comNm")) : String(dma_comInfo.get("comNm")))) + "(" + String(dma_comInfo.get("isurCd")) + ")"; } },
        { childId: "__rb2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb5", fn: function () { return "* 우회상장법인 정보 (" + String(dma_defaultMap.get("objComNm")) + ")"; } },
        { childId: "ipt_corpRegNo1", fn: function () { return String(String(dma_comInfo.get("corpRegNo")).substring(0, 6)); } },
        { childId: "ipt_corpRegNo2", fn: function () { return String(String(dma_comInfo.get("corpRegNo")).substring(6, 13)); } },
        { childId: "ipt_bzRegNo1", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(0, 3)); } },
        { childId: "ipt_bzRegNo2", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(3, 5)); } },
        { childId: "ipt_bzRegNo3", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(5, 10)); } },
        { childId: "ipt_acntclsMmdd1", fn: function () { return String(String((dma_pageContext.get("acntclsMmdd") ?? ""))); } },
        { childId: "ipt_rsltNotiDd", fn: function () { return String(dma_specyvaluInfo.get("rsltNotiDd")); } },
        { childId: "ipt_acntclsMmdd12", fn: function () { return String(String((dma_pageContext.get("acntclsMmdd") ?? ""))); } },
        { childId: "__rb6", fn: function () { return String(((String((dma_pageContext.get("mode") ?? "")) === "new") ? "" : String(dma_comInfo.get("remk")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

