/**
 * @method
 * @name chkDuplicateMbrNo
 * @description chk Duplicate Mbr No 처리
 * @param {*} chkObj chkObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkDuplicateMbrNo = async function (chkObj) {
    if (scwin.agnccomMbr > 1) {
        const mbrNoArr = $c.util.getComponent('slc_listAgnccomMbrNo0');
        let chkDupFlag = false;
        for (let i = 0; i < scwin.agnccomMbr; i++) {
            if (chkObj !== mbrNoArr[i] && chkObj.value === mbrNoArr[i].value) {
                chkDupFlag = true;
                break;
            }
        }
        if (chkDupFlag) {
            await $c.win.alert("상장주선인은 중복하여 선택할 수 없습니다.");
            chkObj.value = "";
            chkObj.focus();
            return false;
        }
    }
    return true;
};

