/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @param {*} frm frm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function (frm) {
    const objArr = new Array(4);
    const mbrNo = $c.util.getComponent('slc_listAgnccomMbrNo0');
    const listChrgNm = $c.util.getComponent('ipt_listChrgNm');
    const listChrgEmail = $c.util.getComponent('ipt_listChrgEmail');
    const listChrgTelNo = $c.util.getComponent('ipt_listChrgTelNo');
    for (let i = 0; i < scwin.agnccomMbr; i++) {
        if (scwin.agnccomMbr === 1) {
            objArr[0] = mbrNo;
            objArr[1] = listChrgNm;
            objArr[2] = listChrgEmail;
            objArr[3] = listChrgTelNo;
        } else {
            objArr[0] = mbrNo[i];
