/**
 * @method
 * @name checkOldMktType
 * @description check Old Mkt Type 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkOldMktType = async function () {
    const oldMktTpCd = $c.util.getComponent('slc_oldSpotIsuTrdMktTpCd');
    const oldListDd = $c.util.getComponent('cal_oldListDd');
    const oldDelistDd = $c.util.getComponent('cal_oldDelistDd');
    if (oldMktTpCd.getValue() === 'N') {
        await $c.win.alert("이전시장은 필수 입력 항목입니다.");
        oldMktTpCd.focus();
        return false;
    }
    if ((oldMktTpCd.getValue() === '1' || oldMktTpCd.getValue() === '2' || oldMktTpCd.getValue() === '6') && ($c.util.getComponent("dma_comInfo").get("oldListDd") == null ? '' : String($c.util.getComponent("dma_comInfo").get("oldListDd"))) === '') {
        await $c.win.alert("이전시장을 선택한 경우 이전상장일자는 필수 입력 항목입니다.");
        oldListDd.focus();
        return false;
    }
    if (($c.util.getComponent("dma_comInfo").get("oldListDd") == null ? '' : String($c.util.getComponent("dma_comInfo").get("oldListDd"))) !== '' && (oldMktTpCd.getValue() === 'N' || (oldMktTpCd.getValue() == null ? '' : String(oldMktTpCd.getValue())) === '')) {
        await $c.win.alert("이전상장일자 항목을 입력하려면 이전시장 항목을 먼저 선택하세요.");
        oldMktTpCd.focus();
        return false;
    }
    if (($c.util.getComponent("dma_comInfo").get("oldDelistDd") == null ? '' : String($c.util.getComponent("dma_comInfo").get("oldDelistDd"))) !== '' && (oldMktTpCd.getValue() === 'N' || (oldMktTpCd.getValue() == null ? '' : String(oldMktTpCd.getValue())) === '')) {
        await $c.win.alert("이전상장폐지일자 항목을 입력하려면 이전시장 항목을 먼저 선택하세요.");
        oldMktTpCd.focus();
        return false;
    }
    return true;
};

