    const ver = scwin.mergeCorp + 1;
    const language = $c.util.getComponent("mergeObjCorpTable");
    let txt = '';
    txt += '		 <input type="text" name="listMergeObjCorpNm" id="listMergeObjCorpNm' + (ver) + '" value="" class="form_search" size="15"/> ';
    txt += '		 <input type="hidden" name="listMergeObjCorpCd" id="listMergeObjCorpCd' + (ver) + '"  value="" />	';
    txt += '		 <a onclick="delListMergeObjCorp(' + ver + ');return false;"><img src="/img/main/x.gif" alt="삭제"></img></a>';
    scwin.mergeCorp++;
    const addedDiv = document.createElement("div");
    addedDiv.id = "added_mergeCorp" + scwin.mergeCorp;
    addedDiv.innerHTML = txt;
    language.appendChild(addedDiv);
};

